CREATE OR REPLACE FUNCTION public.accept_department_invite(p_code text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_invite public.department_invites%ROWTYPE; v_user_id uuid; v_profile_id uuid; BEGIN SELECT auth.uid() INTO v_user_id; IF v_user_id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'not_authenticated'); END IF; SELECT id INTO v_profile_id FROM public.profiles WHERE user_id = v_user_id LIMIT 1; IF v_profile_id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'profile_not_found'); END IF; SELECT * INTO v_invite FROM public.department_invites WHERE code = upper(trim(p_code)) AND expires_at > now() LIMIT 1; IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'invalid_or_expired_code'); END IF; UPDATE public.profiles SET department_id = v_invite.department_id WHERE id = v_profile_id; INSERT INTO public.department_audit_logs(department_id, action, profile_id, details) VALUES (v_invite.department_id, 'accept_invite', v_profile_id, jsonb_build_object('code', v_invite.code, 'invite_id', v_invite.id)); RETURN jsonb_build_object('ok', true, 'department_id', v_invite.department_id); END; $$;
